        new Club { Name = "Frog Choir", Meets = "Wednesday" },
        new Club { Name = "Acorn Artists", Meets = "Friday" });
    db.SaveChanges();
}

// Every club, A to Z.
app.MapGet("/api/clubs", (ClubDb db) =>
    db.Clubs.OrderBy(c => c.Name).ToList());

// Start a new club. It needs a name.
app.MapPost("/api/clubs", (Club club, ClubDb db) =>
{
    if (string.IsNullOrWhiteSpace(club.Name))
        return Results.BadRequest("A club needs a name.");
    db.Clubs.Add(club);
    db.SaveChanges();
    return Results.Created($"/api/clubs/{club.Id}", club);
});

app.Run();

